// WeBjammin — procedural riff/chart generator.
//
// Deterministic: the same seed always produces the same chart, so bundled
// songs can be regenerated byte-for-byte on the device or on the server.
#pragma once

#include <cstdint>
#include <string>

#include "chart/chart.hpp"

namespace wj {

struct GeneratorSettings {
    uint32_t seed = 1;
    double bpm = 120.0;
    int bars = 16;
    int lane_count = 5;
    // 0 = easy, 1 = normal, 2 = hard — controls note density and syncopation.
    int difficulty = 1;
    std::string title = "Generated Riff";
    std::string artist = "WeBjammin Synth";
    std::string charter = "Procedural";
};

// Builds a chart from the settings. Returns false only on invalid settings.
bool generate_riff(Chart& out, const GeneratorSettings& settings, std::string& error);

} // namespace wj
